package com.hbm.client.oilextraction;
import com.hbm.client.model.*;import com.hbm.machine.oilextraction.*;import com.hbm.multiblock.DummyableBlock;import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.*;
/** Actual original HFR derrick and all four animated pumpjack groups, including dynamic rods/cables. */
public final class OilDrillRenderer implements BlockEntityRenderer<OilDrillEntity> {
 public OilDrillRenderer(BlockEntityRendererProvider.Context context){}
 static ResourceLocation texture(OilDrillKind kind){return ResourceLocation.parse("hbm:textures/models/machines/"+kind.config+".png");}static WavefrontMesh model(OilDrillKind kind){return LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),ResourceLocation.parse("hbm:models/machines/"+kind.config+".obj"));}
 static void all(OilDrillKind kind,PoseStack pose,MultiBufferSource buffers,int light,int overlay){LegacyObjRenderer.renderAll(model(kind),pose,buffers.getBuffer(kind==OilDrillKind.WELL?RenderType.entityCutout(texture(kind)):RenderType.entityCutoutNoCull(texture(kind))),light,overlay,-1,LegacyObjRenderer.Convention.HFR);}
 private static void part(String name,PoseStack pose,MultiBufferSource buffers,int light,int overlay){LegacyObjRenderer.render(model(OilDrillKind.PUMPJACK),pose,buffers.getBuffer(RenderType.entityCutout(texture(OilDrillKind.PUMPJACK))),light,overlay,-1,LegacyObjRenderer.Convention.HFR,WavefrontMesh.legacyPart(name));}
 @Override public void render(OilDrillEntity machine,float partial,PoseStack pose,MultiBufferSource buffers,int light,int overlay){float yaw=switch(DummyableBlock.facing(machine.getBlockState())){case NORTH->90;case WEST->180;case SOUTH->270;default->0;};if(machine.kind()==OilDrillKind.WELL)yaw+=90;var transform=new org.joml.Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.toRadians(yaw));LegacyContactShadows.render(machine,model(machine.kind()),transform,pose,buffers);pose.pushPose();pose.translate(.5,0,.5);pose.mulPose(Axis.YP.rotationDegrees(yaw));if(machine.kind()==OilDrillKind.WELL)all(machine.kind(),pose,buffers,light,overlay);else{float rotation=machine.prevRot+(machine.rot-machine.prevRot)*partial;double rad=Math.toRadians(rotation);part("Base",pose,buffers,light,overlay);pose.pushPose();pose.translate(0,1.5,-5.5);pose.mulPose(Axis.XP.rotationDegrees(rotation-90));pose.translate(0,-1.5,5.5);part("Rotor",pose,buffers,light,overlay);pose.popPose();pose.pushPose();pose.translate(0,3.5,-3.5);pose.mulPose(Axis.XP.rotationDegrees((float)(Math.toDegrees(Math.sin(rad))*.25)));pose.translate(0,-3.5,3.5);part("Head",pose,buffers,light,overlay);pose.popPose();pose.pushPose();pose.translate(0,-Math.sin(rad),0);part("Carriage",pose,buffers,light,overlay);pose.popPose();rods(rotation,pose,buffers);}pose.popPose();}
 // Minecraft1.7 Vec3.rotateAroundX: y'=y*cos+z*sin; z'=z*cos-y*sin (opposite standard positive matrix).
 private static Vec3 rotate(Vec3 v,double angle){double sin=net.minecraft.util.Mth.sin((float)angle),cos=net.minecraft.util.Mth.cos((float)angle);return new Vec3(v.x,v.y*cos+v.z*sin,v.z*cos-v.y*sin);}
 private static void vertex(VertexConsumer out,PoseStack pose,double x,double y,double z,int color){out.addVertex(pose.last(),(float)x,(float)y,(float)z).setColor(color);}
 private static void rods(float rotation,PoseStack pose,MultiBufferSource buffers){var out=buffers.getBuffer(OilDrillRenderTypes.RODS);double radians=Math.toRadians(rotation);var back=rotate(new Vec3(0,0,-2),-(float)Math.sin(radians)*.25F);var rotor=rotate(new Vec3(0,.5,0),-(float)Math.toRadians(rotation-90));for(int i=-1;i<=1;i+=2){vertex(out,pose,.53125*i,1.5+rotor.y,-5.5+rotor.z-.0625,0xff7f7f7f);vertex(out,pose,.53125*i,1.5+rotor.y,-5.5+rotor.z+.0625,0xff7f7f7f);vertex(out,pose,.53125*i,3.5+back.y,-3.5+back.z+.0625,0xff7f7f7f);vertex(out,pose,.53125*i,3.5+back.y,-3.5+back.z-.0625,0xff7f7f7f);}double height=-Math.sin(radians);for(int i=-1;i<=1;i+=2){float pivot=-(float)(Math.sin(radians)*.25);var front=rotate(new Vec3(0,0,1),pivot);var radius=rotate(new Vec3(0,0,2.53125),pivot);radius=rotate(radius,-(float)Math.toRadians(360D/32*-3));for(int j=0;j<4;j++){double y=front.y+radius.y,z=radius.y<0?3.5+.03125*.5:front.z+radius.z;vertex(out,pose,(.25-.03125)*i,3.5+y,-3.5+z,0xff333333);vertex(out,pose,(.25+.03125)*i,3.5+y,-3.5+z,0xff333333);radius=rotate(radius,-(float)Math.toRadians(360D/32));y=front.y+radius.y;z=radius.y<0?3.5+.03125*.5:front.z+radius.z;vertex(out,pose,(.25+.03125)*i,3.5+y,-3.5+z,0xff333333);vertex(out,pose,(.25-.03125)*i,3.5+y,-3.5+z,0xff333333);}double y=front.y+radius.y,z=radius.y<0?3.5+.03125*.5:front.z+radius.z;vertex(out,pose,(.25+.03125)*i,3.5+y,-3.5+z,0xff333333);vertex(out,pose,(.25-.03125)*i,3.5+y,-3.5+z,0xff333333);vertex(out,pose,(.25-.03125)*i,2+height,0,0xff333333);vertex(out,pose,(.25+.03125)*i,2+height,0,0xff333333);}double p=.03125;double[][] vertices={{p,height+1.5,p},{-p,height+1.5,-p},{-p,.75,-p},{p,.75,p},{-p,height+1.5,p},{p,height+1.5,-p},{p,.75,-p},{-p,.75,p}};for(var v:vertices)vertex(out,pose,v[0],v[1],v[2],0xff333333);}
 @Override public boolean shouldRenderOffScreen(OilDrillEntity machine){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(OilDrillEntity machine){var p=machine.getBlockPos();return machine.kind()==OilDrillKind.WELL?new AABB(p.getX()-1,p.getY(),p.getZ()-1,p.getX()+2,p.getY()+10,p.getZ()+2):new AABB(p.getX()-7,p.getY(),p.getZ()-7,p.getX()+8,p.getY()+6,p.getZ()+8);}
}
